1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const CURSE_SURCHARGE_RATE = 0.5;
4	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
5	const HIGH_ENCHANTMENT_THRESHOLD = 5;
6	const LOYALTY_DISCOUNT_RATE = 0.2;
7	const LOYALTY_YEARS_THRESHOLD = 2;
8	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
9	
10	const COMPONENT_BASE_PREMIUM = 25;
11	const BLOCK_SIZE = 3;
12	const BLOCK_PREMIUM = 60;
13	
14	const DEDUCTIBLE = 100;
15	const CAP_MULTIPLIER = 2;
16	
17	const BASE_PREMIUM: Record<string, number> = {
18	  sword: 100,
19	  amulet: 60,
20	  staff: 80,
21	  potion: 40,
22	  rune: COMPONENT_BASE_PREMIUM,
23	  moonstone: COMPONENT_BASE_PREMIUM,
24	};
25	
26	const INSURANCE_VALUE: Record<string, number> = {
27	  sword: 1000,
28	  amulet: 600,
29	  staff: 800,
30	  potion: 400,
31	  rune: 250,
32	  moonstone: 250,
33	};
34	
35	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
36	
37	type Item = { type: string; cursed?: boolean; enchantment?: number };
38	type Customer = { yearsWithMHPCO: number };
39	type Damage = { itemType: string; amount: number };
40	type QuoteStep = { op: "quote"; items: Item[] };
41	type ClaimStep = {
42	  op: "claim";
43	  policy: number;
44	  incident: { cause: string; damages: Damage[] };
45	};
46	type Step = QuoteStep | ClaimStep;
47	type Scenario = { customer: Customer; steps: Step[] };
48	
49	type QuoteResult = { premium: number };
50	type ClaimResult = { payout: number; remainingCap: number };
51	type StepResult = QuoteResult | ClaimResult;
52	
53	type PolicyState = { items: Item[]; insuranceSum: number; remainingCap: number };
54	
55	const countsByType = (items: Item[]): Map<string, number> =>
56	  items.reduce(
57	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
58	    new Map<string, number>(),
59	  );
60	
61	const groupBase = (type: string, count: number): number =>
62	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE
63	    ? BLOCK_PREMIUM
64	    : count * BASE_PREMIUM[type];
65	
66	const itemsBase = (items: Item[]): number => {
67	  let total = 0;
68	  for (const [type, count] of countsByType(items)) {
69	    total += groupBase(type, count);
70	  }
71	  return total;
72	};
73	
74	const isCursed = (item: Item): boolean => item.cursed === true;
75	const isHighlyEnchanted = (item: Item): boolean =>
76	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
77	
78	const itemSurcharge = (item: Item): number => {
79	  const base = BASE_PREMIUM[item.type];
80	  const curseSurcharge = isCursed(item) ? base * CURSE_SURCHARGE_RATE : 0;
81	  const highEnchantmentSurcharge = isHighlyEnchanted(item)
82	    ? base * HIGH_ENCHANTMENT_SURCHARGE_RATE
83	    : 0;
84	  return curseSurcharge + highEnchantmentSurcharge;
85	};
86	
87	const itemSurchargesTotal = (items: Item[]): number =>
88	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
89	
90	const roundUpInFavorOfInsurer = (amount: number): number =>
91	  Math.ceil(Math.round(amount * 1e6) / 1e6);
92	
93	const roundDownInFavorOfInsurer = (amount: number): number =>
94	  Math.floor(Math.round(amount * 1e6) / 1e6);
95	
96	const isLoyal = (customer: Customer): boolean =>
97	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
98	
99	const loyaltyDiscount = (customer: Customer, policyBase: number): number =>
100	  isLoyal(customer) ? policyBase * LOYALTY_DISCOUNT_RATE : 0;
101	
102	const firstInsuranceSurcharge = (policyBase: number): number =>
103	  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
104	
105	const followUpDiscount = (policyBase: number, isFollowUp: boolean): number =>
106	  isFollowUp ? policyBase * FOLLOW_UP_DISCOUNT_RATE : 0;
107	
108	const quotePremium = (items: Item[], customer: Customer, isFollowUp: boolean): number => {
109	  const policyBase = itemsBase(items);
110	  return roundUpInFavorOfInsurer(
111	    policyBase +
112	      itemSurchargesTotal(items) +
113	      firstInsuranceSurcharge(policyBase) -
114	      loyaltyDiscount(customer, policyBase) -
115	      followUpDiscount(policyBase, isFollowUp) +
116	      PROCESSING_FEE,
117	  );
118	};
119	
120	const insuranceSum = (items: Item[]): number =>
121	  items.reduce((sum, item) => sum + INSURANCE_VALUE[item.type], 0);
122	
123	const createPolicy = (items: Item[]): PolicyState => {
124	  const sum = insuranceSum(items);
125	  return { items, insuranceSum: sum, remainingCap: sum * CAP_MULTIPLIER };
126	};
127	
128	const damagePayout = (damage: Damage): number => damage.amount - DEDUCTIBLE;
129	
130	const processClaim = (policy: PolicyState, damages: Damage[]): ClaimResult => {
131	  const desired = damages.reduce((sum, d) => sum + damagePayout(d), 0);
132	  const payout = roundDownInFavorOfInsurer(Math.min(desired, policy.remainingCap));
133	  policy.remainingCap -= payout;
134	  return { payout, remainingCap: policy.remainingCap };
135	};
136	
137	export const runScenario = (scenario: unknown): unknown => {
138	  const s = scenario as Scenario;
139	  const policies = new Map<number, PolicyState>();
140	  let quoteCount = 0;
141	  const results: StepResult[] = s.steps.map((step, index) => {
142	    if (step.op === "quote") {
143	      const isFollowUp = quoteCount > 0;
144	      quoteCount += 1;
145	      policies.set(index, createPolicy(step.items));
146	      return { premium: quotePremium(step.items, s.customer, isFollowUp) };
147	    }
148	    const policy = policies.get(step.policy)!;
149	    return processClaim(policy, step.incident.damages);
150	  });
151	  return { results };
152	};
